    private static IReadOnlyList<FxEffectDefAsset?> ReplaceFxEffectDefAssetItem(IReadOnlyList<FxEffectDefAsset?> source, int index, FxEffectDefAsset? value)
    {
        ArgumentOutOfRangeException.ThrowIfNegative(index);
        if (index >= source.Count) throw new ArgumentOutOfRangeException(nameof(index));
        var result = source.ToArray();
        result[index] = value;
        return Array.AsReadOnly(result);
    }

